master_compiler_compile:
    push rbp
    mov rbp, rsp
    
    ; rdi: language ID
    ; rsi: source code buffer
    ; rdx: source code size
    ; rcx: output buffer
    ; r8: output buffer size
    
    ; Route to appropriate language compiler
    cmp rdi, 1
    je .compile_c
    cmp rdi, 2
    je .compile_c__
    cmp rdi, 3
    je .compile_java
    cmp rdi, 4
    je .compile_python
    cmp rdi, 5
    je .compile_javascript
    cmp rdi, 6
    je .compile_typescript
    cmp rdi, 7
    je .compile_rust
    cmp rdi, 8
    je .compile_go
    cmp rdi, 9
